"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["5300"],{88135(e){e.exports=JSON.parse('{"id":"F434","slug":"covered-interest-arbitrage","name":"Covered Interest Parity and Arbitrage","subject":"International Finance","section":"Global Finance","topic":"Interest rate parity (covered and uncovered)","level":"Intermediate","aliases":["interest rate parity","CIP","covered arbitrage","forward premium deviation"],"formula":{"latex":"\\\\frac{F}{S}=\\\\frac{1+r_{d}T}{1+r_{f}T},\\\\quad \\\\text{Profit}=\\\\frac{K}{S}(1+r_{f}T)F_{mkt}-K(1+r_{d}T)","also":[],"text":"Parity says the forward rate F = S x (1 + domestic rate T) / (1 + foreign rate T). If the market forward differs, borrow where it is cheaper, convert at spot, invest abroad, and sell the proceeds forward: profit = foreign proceeds at the market forward - domestic proceeds. Compare: invest K in domestic currency = K x (1 + r_d T)"},"symbols":[{"symbol":"S","meaning":"Spot rate (domestic per foreign)","unit":"rate"},{"symbol":"F_mkt","meaning":"Forward rate quoted in the market","unit":"rate"},{"symbol":"K","meaning":"Amount invested (domestic currency)","unit":"money"}],"when_to_use":"Use it to test whether the forward rate is in line with interest rates. If the market forward is higher than parity, buying the foreign currency spot, investing it and selling it forward locks in more than the domestic deposit pays, a risk-free profit. In real markets the gap is usually smaller than costs, except in stress, when funding frictions can open a persistent gap (the cross-currency basis).","worked_example":{"problem":"EUR/USD spot is 1.0850, the 180-day USD rate is 5%, the EUR rate 3%, and the market 180-day forward is 1.0950. You have 1,000,000 USD.","inputs":{"s":1.085,"fm":1.095,"rd":5,"rf":3,"t":180,"k":1000000},"steps":[{"label":"Parity forward","working":"1.085 x (1+0.05 x 180 / 360) / (1+0.03 x 180 / 360)","value":"1.09569"},{"label":"Market forward minus parity, in pips","working":"(1.095-1.09569) x 10000","value":"-6.9"},{"label":"USD deposit proceeds","working":"1,000,000 x (1+0.05 x 180 / 360)","value":"1,025,000.00"},{"label":"Covered foreign deposit: convert, invest, sell forward","working":"1,000,000 / 1.085 x (1+0.03 x 180 / 360) x 1.095","value":"1,024,354.84"},{"label":"Profit = covered proceeds - USD proceeds","working":"cov-1,025,000","value":"-645.16"}],"answer":"Parity gives a forward of 1.09569, but the market quotes 1.0950, -6.9 pips higher. Investing in USD returns 1,025,000.00. Converting to euros, investing at 3% and selling forward gives 1,024,354.84, a risk-free profit of -645.16 (a negative number would mean the opposite loop is the profitable one)."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Spot rate (USD per EUR)","unit":"","type":"number","default":1.085,"hint":""},{"id":"fm","label":"Market forward rate","unit":"","type":"number","default":1.095,"hint":""},{"id":"rd","label":"USD interest rate","unit":"%","type":"number","default":5,"hint":""},{"id":"rf","label":"EUR interest rate","unit":"%","type":"number","default":3,"hint":""},{"id":"t","label":"Days","unit":"days","type":"number","default":180,"hint":"","min":1},{"id":"k","label":"Amount in USD","unit":"money","type":"number","default":1000000,"hint":""}],"checks":[{"expr":"s>0 and fm>0 and k>0","message":"Rates and the amount must be above zero."}],"steps":[{"id":"fp","label":"Parity forward","expr":"s*(1+rd*t/360)/(1+rf*t/360)","format":"num5"},{"id":"dev","label":"Market forward minus parity, in pips","expr":"(fm-fp)*10000","format":"num1"},{"id":"usd","label":"USD deposit proceeds","expr":"k*(1+rd*t/360)","format":"money"},{"id":"cov","label":"Covered foreign deposit: convert, invest, sell forward","expr":"k/s*(1+rf*t/360)*fm","format":"money"},{"id":"profit","label":"Profit = covered proceeds - USD proceeds","expr":"cov-usd","format":"money"}],"results":["fp","dev","profit"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"fp":1.0956896551724138,"dev":-6.896551724138167,"usd":1024999.9999999999,"cov":1024354.8387096772,"profit":-645.1612903226633}},"finder":{"finds":"Whether a forward rate offers a free profit","needs":"Spot, market forward, both rates, days, amount"},"related":[{"slug":"fx-forward-points","name":"Forward Exchange Rate and Forward Points"},{"slug":"uncovered-interest-parity","name":"Uncovered Interest Parity and Unhedged Return"},{"slug":"fx-forward-hedge","name":"FX Forward Hedge and Covered Interest Parity"}],"related_ids":["F433","F435","F392"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mfrac><mi>F</mi><mi>S</mi></mfrac><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>d</mi></msub><mi>T</mi></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub><mi>T</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Profit</mtext><mo>=</mo><mfrac><mi>K</mi><mi>S</mi></mfrac><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub><mi>T</mi><mo stretchy=\\"false\\">)</mo><msub><mi>F</mi><mrow><mi>m</mi><mi>k</mi><mi>t</mi></mrow></msub><mo>\u2212</mo><mi>K</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>d</mi></msub><mi>T</mi><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">\\\\frac{F}{S}=\\\\frac{1+r_{d}T}{1+r_{f}T},\\\\quad \\\\text{Profit}=\\\\frac{K}{S}(1+r_{f}T)F_{mkt}-K(1+r_{d}T)</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"covered-bond-overcollateralization","name":"Covered Bond Overcollateralization"},"next":{"slug":"cir-moments-feller","name":"Cox-Ingersoll-Ross Moments and Feller Condition"},"lesson":null,"total":522}')}}]);